func TestGcodeReplaceToolNum(t *testing.T) {
	t.Run("replace gcode", func(t *testing.T) {
		cases := []struct {
			raw  string
			want string
		}{
			{"T0 ; tool T0", "T0  ; tool T0"},
			{"T1 ; tool T1", "T1  ; tool T1"},
			{"T3 ; tool T3", "T1  ; tool T3"},
			{"T63 ; tool T63", "T1  ; tool T63"},
			{"M104 S255", "M104 S255"},
			{"M109 S255 C2 W1", "M109 S255 C2 W1"},
			{"M104 T0 S200", "M104 T0 S200"},
			{"M104 T1 S200", "M104 T1 S200"},
			{"M104 T3 S200", "M104 T1 S200"},
			{"M104 T63 S200", "M104 T1 S200"},
			{"M106 S255", "M106 S255"},
			{"M107", "M107"},
			{"M106 P0 S200", "M106 P0 S200"},
			{"M106 P62 S200", "M106 P0 S200"},
			{"M107 P0 ; fan off", "M107 P0 ; fan off"},
			{"M107 P62 ; fan off", "M107 P0 ; fan off"},
			{"M301 E3 T0", "M301 E1 T0"},
			{"M303 E4 T1", "M303 E0 T1"},
			{"M108 T33 ; fake cmd", "M108 T33 ; fake cmd"},
			{"G1 T33", "G1 T33"},
		}

		for _, tc := range cases {
			g, err := ParseGcodeBlock(tc.raw)
			if err != nil {
				t.Fatal(err)
			}
			gcodes := []*GcodeBlock{g}
			result := GcodeReplaceToolNum(gcodes)
			if result[0].String() != tc.want {
				t.Errorf("Got %q, want %q", g, tc.want)
			}
		}
	})

	comp := func(gcodes []*GcodeBlock, want []*GcodeBlock) {
		got := GcodeReplaceToolNum(gcodes)
		if (reflect.DeepEqual(got, want)) != true {
			results := make([]string, 0, len(got)+len(want)+1)
			for _, g := range got {
				results = append(results, g.String())
			}
			results = append(results, "==========>")
			for _, g := range want {
				results = append(results, g.String())
			}
			t.Error(strings.Join(results, "\n"))
		}
	}
	t.Run("replace comment 1", func(t *testing.T) {
		gcodes := _parseGcodes(`
T0
T1
; filament used [mm] = 5989.21, 4703.92
; filament used [cm3] = 14.41, 11.31
; filament used [g] = 17.86, 14.03
; filament cost = 0, 0, 0, 1.07, 0.84; total filament used [g] = 31.89
		`)
		want := _parseGcodes(`
T0
T1
; filament used [mm] = 5989.21,4703.92
; filament used [cm3] = 14.41,11.31
; filament used [g] = 17.86,14.03
; filament cost = 0, 0, 0, 1.07, 0.84; total filament used [g] = 31.89
		`)
		comp(gcodes, want)
	})

	t.Run("replace comment 2", func(t *testing.T) {
		gcodes := _parseGcodes(`
T1
; filament used [mm] = 0, 4703.92
; filament used [cm3] = 0, 11.31
; filament used [g] = 0, 14.03
		`)
		want := _parseGcodes(`
T1
; filament used [mm] = 0,4703.92
; filament used [cm3] = 0,11.31
; filament used [g] = 0,14.03
		`)
		comp(gcodes, want)
	})

	t.Run("replace comment 3", func(t *testing.T) {
		gcodes := _parseGcodes(`
T3
T2
; filament used [mm] = 0, 0, 5989.21, 4703.92
; filament used [cm3] = 0, 0, 14.41, 11.31
; filament used [g] = 0, 0, 17.86, 14.03
		`)
		want := _parseGcodes(`
T1
T0
; filament used [mm] = 5989.21,4703.92
; filament used [cm3] = 14.41,11.31
; filament used [g] = 17.86,14.03
		`)
		comp(gcodes, want)
	})

	t.Run("replace comment 4", func(t *testing.T) {
		gcodes := _parseGcodes(`
T2
T1
; filament used [mm] = 0, 9, 5989.21, 4703.92
; filament_type = PLA;ABS; PETG; ASA
; first_layer_bed_temperature = 70
; hot_plate_temp_initial_layer = 55, 95, 70,100
		`)
		want := _parseGcodes(`
T0
T1
; filament used [mm] = 5989.21,9
; filament_type = PETG;ABS
; first_layer_bed_temperature = 70
; hot_plate_temp_initial_layer = 70,95
		`)
		comp(gcodes, want)
	})
}

func TestGcode(t *testing.T) {
	{ // NewGcode
		cases := map[string]struct {
			word  byte
			addr  string
			valid bool
		}{
			"*0X": {'*', "0X", false},
			"y":   {'Y', "", false},
			"0":   {'0', "", false},

			"X*": {'X', "*", true},
			"B":  {'B', "", true},
			"B0": {'B', "0", true},

			"G0":   {'G', "0", true},
			"E-3":  {'E', "-3", true},
			"G.1":  {'G', ".1", true},
			"G-.1": {'G', "-.1", true},

			"E.00001":       {'E', ".00001", true},
			"E-.00001":      {'E', "-.00001", true},
			"E.000001":      {'E', ".000001", true},
			"X-9999.000001": {'X', "-9999.000001", true},
		}
		for raw, tc := range cases {
			t.Run(raw, func(t *testing.T) {
				g, err := NewGcode(tc.word, tc.addr)
				if tc.valid {
					if err != nil {
						t.Errorf("unexpected error: %v", err)
					} else {
						if g.String() != raw {
							t.Errorf("(%s) but want(%s)", g, raw)
						}
					}
				} else {
					if err == nil && g.String() == raw {
						t.Errorf("unexpected success: (%v) want (%s)", g, raw)
					}
				}
			})
		}
	}

	{ // ParseGcode
		_, err := ParseGcode("")
		if err == nil || err.Error() != ErrEmptyString.Error() {
			t.Errorf("unexpected error: %v", err)
		}
	}

	{ // SetAddr
		cases := []struct {
			want   string
			origin *Gcode
			new    any
			err    error
		}{
			{"E0.00000", &Gcode{'E', "6", 1 + uint16(len("6"))}, 0.000001, nil}, // 0.000001 < 0.00001
			{"E0.00001", &Gcode{'E', "6", 1 + uint16(len("6"))}, 0.00001, nil},
			{"E3", &Gcode{'E', "", 1 + uint16(len(""))}, 3, nil},
			{"E4", &Gcode{'E', "", 1 + uint16(len(""))}, int32(4), nil},
			{"E5", &Gcode{'E', "", 1 + uint16(len(""))}, int64(5), nil},
			{"E6", &Gcode{'E', "", 1 + uint16(len(""))}, uint(6), nil},
			{"E7", &Gcode{'E', "", 1 + uint16(len(""))}, uint32(7), nil},
			{"E8", &Gcode{'E', "", 1 + uint16(len(""))}, uint64(8), nil},
			{"E9.10000", &Gcode{'E', "", 1 + uint16(len(""))}, float32(9.1), nil}, // E.5f
			{"E9.20000", &Gcode{'E', "", 1 + uint16(len(""))}, float64(9.2), nil},
			{"R", &Gcode{'R', "999", 1 + uint16(len("999"))}, nil, nil},
			{"Z", &Gcode{'Z', "999", 1 + uint16(len("999"))}, false, errors.New("unsupported addr type bool")},
			{"S", &Gcode{'S', "999", 1 + uint16(len("999"))}, errors.ErrUnsupported, errors.New("unsupported addr type *errors.errorString")},
			{"X0.001", &Gcode{'X', "", 1 + uint16(len(""))}, 0.001, nil},
			{"X-0.001", &Gcode{'X', "", 1 + uint16(len(""))}, -0.001, nil},
			{"E1.23457", &Gcode{'E', "", 1 + uint16(len(""))}, 1.23456789, nil},        // E.5f
			{"E-1.23457", &Gcode{'E', "", 1 + uint16(len(""))}, -1.23456789, nil},      // E.5f
			{"E-1.23456789", &Gcode{'E', "", 1 + uint16(len(""))}, "-1.23456789", nil}, // string
			{"X0.000", &Gcode{'X', "6", 1 + uint16(len("6"))}, 0.0001, nil},            // 0.0001 < 0.001
			{"X1.235", &Gcode{'X', "", 1 + uint16(len(""))}, 1.23456789, nil},          // .3f
		}

		for _, c := range cases {
			t.Run(c.want, func(t *testing.T) {
				if err := c.origin.SetAddr(c.new); err != nil && c.err != nil {
					if err.Error() != c.err.Error() {
						t.Errorf("unexpected error: %v", err)
					}
					return
				}
				if c.origin.String() != c.want {
					t.Errorf("(%s) but want(%s)", c.origin, c.want)
				}
			})
		}
	}

	{ // AddrAs
		var origin *Gcode

		var str string
		origin = &Gcode{'X', "6", 1 + uint16(len("6"))}
		origin.AddrAs(&str)
		if str != "6" {
			t.Errorf("unexpected addr: %v", str)
		}

		var i int
		origin.AddrAs(&i)
		if i != 6 {
			t.Errorf("unexpected addr: %v", i)
		}

		var i32 int32
		origin.AddrAs(&i32)
		if i32 != 6 {
			t.Errorf("unexpected addr: %v", i32)
		}

		var f32 float32
		origin.AddrAs(&f32)
		if f32 != 6 {
			t.Errorf("unexpected addr: %v", f32)
		}

		origin = &Gcode{'X', ".000001", 1 + uint16(len(".000001"))}
		origin.AddrAs(&f32)
		if f32 != 0.000001 {
			t.Errorf("unexpected addr: %v", f32)
		}

		var f64 float64
		if err := origin.AddrAs(&f64); err == nil || err.Error() != "unsupported addr type as *float64" {
			t.Errorf("unexpected error: %v", err)
		}
	}

}

func TestParseGcodeBlock(t *testing.T) {
	{ // validate all funcs
		s := " M1 X1.23 Y2.456 Z.3 E-.004 F500000 ; a comment T63 "
		g, err := ParseGcodeBlock(s)
		if err != nil {
			t.Errorf("unexpected error: %v", err)
		}

		if g.String() != strings.TrimSpace(s) {
			t.Errorf("unexpected string: %v", g.String())
		}
		if !g.Is("M1") {
			t.Errorf("unexpected command: %v", g.Cmd().String())
		}
		if !g.HasParam('X') {
			t.Errorf("expected param X but not: %v", g.Cmd().String())
		}
		if g.HasParam('M') {
			t.Errorf("unexpected param M: %v", g.Cmd().String())
		}
		var e float32
		if err := g.GetParam('E', &e); err == nil && e != -0.004 {
			t.Errorf("expected -0.004 but not: %v", e)
		} else if err != nil {
			t.Errorf("unexpected error: %v", err)
		}
		if new := g.Copy(); new.String() != g.String() {
			t.Errorf("unexpected copy: %v", new.String())
		}
		if g.Comment() != "; a comment T63" {
			t.Errorf("unexpected comment: %v", g.Comment())
		}
		if tool, err := g.GetToolNum(); tool != 63 || err != nil {
			t.Errorf("unexpected tool: %v, err: %s, comment: %s", tool, err, g.Comment())
		}
		g.SetComment("; another comment %d", 123)
		if g.Comment() != "; another comment 123" {
			t.Errorf("unexpected comment: %v", g.Comment())
		}
		g.AppendComment(", append %.3f", .456)
		comment := "; another comment 123, append 0.456"
		if g.Comment() != comment {
			t.Errorf("unexpected comment: %v", g.Comment())
		}
		if r := g.Format("%m"); r != comment {
			t.Errorf("unexpected comment: %v", r)
		}
		format := "this is a %c gcode"
		if r := g.Format(format); r != "this is a M1 gcode" {
			t.Errorf("unexpected format: %q", r)
		}
		if !g.InComment("0.456") {
			t.Errorf("expect 0.456 in comment but not: %v", g.Comment())
		}
	}
	{ // get tool num
		cases := map[string]int32{
			"M104 S154 ;standby T0":     0,
			"M104 S154 ; standby  T64;": 64,
			"M104 T0 S154 ;standby   T": 0,
			"M104 T0 S154 ; standby T9": 0,
			"M106 P3 S154":              3,
			"M106 T0 P4 S154":           4,
			"M107 T0 P5 S154":           5,
			"M303 T1 P2 E3 S154":        3,
			"T0":                        0,
			"T-1":                       -1,
			"T0;T1":                     0,
			"M0 T-1;T-3":                -1,
			";T1":                       1,
			// ";T-3":                      -3, // not support in comment
		}

		for s, want := range cases {
			g, err := ParseGcodeBlock(s)
			if err != nil {
				t.Errorf("unexpected error: %v", err)
			}
			if tool, err := g.GetToolNum(); tool != want || err != nil {
				t.Errorf("unexpected tool: %v, err: %s, %s", tool, err, g)
			}
		}
	}

	{
		// raw -> want
		cases := [][2]string{
			{" G0.1   X1.23 Y.456000 F500000 ", "G0.1 X1.23 Y.456000 F500000"},
			{"G0 X1.23 Y.456000 ; comment", "G0 X1.23 Y.456000 ; comment"},
			{" T64", "T64"},
			{"M900 K-.04", "M900 K-.04"},
			{"; config = value\nss ", "; config = value\nss"},
			{";; a comment ", ";; a comment"},
			{";", ";"},
			{"G1 123", "G1"},
			{"M220 R", "M220 R"},
			{"G28 X Y", "G28 X Y"},
			{"X Y Z", "X Y Z"},
			{"G28 N*", "G28 N*"},
			{"N**", "N**"},
			{"N;comm", "N  ;comm"}, // N as command, %p be replaced as a space
		}

		for _, c := range cases {
			result, err := ParseGcodeBlock(c[0])
			if err != nil {
				t.Errorf("unexpected error: %v (%s)", err, c[0])
				break
			}
			if result.String() != c[1] {
				t.Errorf("(%v) but want(%v)", result, c[1])
			}
		}
	}
}

func TestGcodeFixOrcaToolUnload(t *testing.T) {
	gcode := `
M104 S199
; LAYER_HEIGHT: 0.2
; FEATURE: Prime tower
; LINE_WIDTH: 0.5
;--------------------
; CP TOOLCHANGE START
; toolchange #2
; material : PETG -> PET
;--------------------
M220 B
M220 S100
; CP TOOLCHANGE UNLOAD
; LINE_WIDTH: 0.6
; LINE_WIDTH: 0.5
M104 S250 T0
M104 S278
M104 S255; T1
; Cooling park
G4 S0
G1 E-2 F2100
; CP TOOLCHANGE END
;------------------
M104 S299
`
	gcodes := _parseGcodes(gcode)

	comp := `
M104 S199
; LAYER_HEIGHT: 0.2
; FEATURE: Prime tower
; LINE_WIDTH: 0.5
;--------------------
; CP TOOLCHANGE START
; toolchange #2
; material : PETG -> PET
;--------------------
M220 B
M220 S100
; CP TOOLCHANGE UNLOAD
; LINE_WIDTH: 0.6
; LINE_WIDTH: 0.5
M104 S250 T0
;(Fixed: remove: M104 S278)
M104 S255; T1
; Cooling park
G4 S0
G1 E-2 F2100
; CP TOOLCHANGE END
;------------------
M104 S299
`
	comp_gcodes := _parseGcodes(comp)

	result := GcodeFixOrcaToolUnload(gcodes)
	if (reflect.DeepEqual(result, comp_gcodes)) != true {
		results := make([]string, 0, len(result)+len(comp_gcodes)+1)
		for _, g := range result {
			results = append(results, g.String())
		}
		results = append(results, "==========>")
		for _, g := range comp_gcodes {
			results = append(results, g.String())
		}
		t.Error(strings.Join(results, "\n"))
	}
}

func _padToLines(n int) string {
	var sb strings.Builder
	for i := 0; i < n; i++ {
		sb.WriteString("G0 X0 Y0\n")
	}
	return sb.String()
}

func _validPrusaSlicerGcode() string {
	return `; generated by PrusaSlicer 2.7.0
; printer_model = A350
; bed_shape = 0x0,320x350
; first_layer_temperature = 215, 220
; first_layer_bed_temperature = 60, 65
; nozzle_diameter = 0.4, 0.4
; layer_height = 0.2
; total_layer_number = 150
; filament_type = PLA,ABS
; filament used [mm] = 5000, 3000
; filament used [g] = 12.5, 7.5
; estimated printing time (normal mode) = 1h 30m 0s
; retract_length = 1.2, 1.5
; retract_length_toolchange = 3.0, 3.5
; max_print_speed = 100
; min_x = 10
; min_y = 20
; min_z = 0.2
; max_x = 300
; max_y = 330
; max_z = 50.4
; printer_notes = Don't lose focus!
` + _padToLines(10)
}

func TestParseParams_ValidPrusaSlicer(t *testing.T) {
	gcodes := _parseGcodes(_validPrusaSlicerGcode())
	if err := ParseParams(gcodes); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	p := Params
	if p.Model != ModelA350 {
		t.Errorf("Model: got %q, want %q", p.Model, ModelA350)
	}
	if p.Version != 0 {
		t.Errorf("Version: got %d, want 0", p.Version)
	}
	if p.LayerHeight != 0.2 {
		t.Errorf("LayerHeight: got %f, want 0.2", p.LayerHeight)
	}
	if p.TotalLayers != 150 {
		t.Errorf("TotalLayers: got %d, want 150", p.TotalLayers)
	}
	if p.NozzleTemperatures[0] != 215 || p.NozzleTemperatures[1] != 220 {
		t.Errorf("NozzleTemperatures: got %v, want [215, 220]", p.NozzleTemperatures)
	}
	if p.BedTemperatures[0] != 60 || p.BedTemperatures[1] != 65 {
		t.Errorf("BedTemperatures: got %v, want [60, 65]", p.BedTemperatures)
	}
	if p.NozzleDiameters[0] != 0.4 || p.NozzleDiameters[1] != 0.4 {
		t.Errorf("NozzleDiameters: got %v, want [0.4, 0.4]", p.NozzleDiameters)
	}
	if p.FilamentTypes[0] != "PLA" || p.FilamentTypes[1] != "ABS" {
		t.Errorf("FilamentTypes: got %v, want [PLA, ABS]", p.FilamentTypes)
	}
	if p.FilamentUsed[0] != 5000 || p.FilamentUsed[1] != 3000 {
		t.Errorf("FilamentUsed: got %v, want [5000, 3000]", p.FilamentUsed)
	}
	if p.FilamentUsedWeight[0] != 12.5 || p.FilamentUsedWeight[1] != 7.5 {
		t.Errorf("FilamentUsedWeight: got %v, want [12.5, 7.5]", p.FilamentUsedWeight)
	}
	if p.EstimatedTimeSec != 5400 {
		t.Errorf("EstimatedTimeSec: got %d, want 5400", p.EstimatedTimeSec)
	}
	if p.Retractions[0] != 1.2 || p.Retractions[1] != 1.5 {
		t.Errorf("Retractions: got %v, want [1.2, 1.5]", p.Retractions)
	}
	if p.SwitchRetraction[0] != 3.0 || p.SwitchRetraction[1] != 3.5 {
		t.Errorf("SwitchRetraction: got %v, want [3.0, 3.5]", p.SwitchRetraction)
	}
	if p.PrintSpeedSec != 100 {
		t.Errorf("PrintSpeedSec: got %f, want 100", p.PrintSpeedSec)
	}
	if p.MinX != 10 || p.MinY != 20 || p.MinZ != 0.2 {
		t.Errorf("Min: got (%f,%f,%f), want (10,20,0.2)", p.MinX, p.MinY, p.MinZ)
	}
	if p.MaxX != 300 || p.MaxY != 330 || p.MaxZ != 50.4 {
		t.Errorf("Max: got (%f,%f,%f), want (300,330,50.4)", p.MaxX, p.MaxY, p.MaxZ)
	}
	if !p.LeftExtruderUsed || !p.RightExtruderUsed {
		t.Errorf("ExtruderUsed: got (%v,%v), want (true,true)", p.LeftExtruderUsed, p.RightExtruderUsed)
	}
	if p.ToolHead != ToolheadDual {
		t.Errorf("ToolHead: got %q, want %q", p.ToolHead, ToolheadDual)
	}
	if p.PrintMode != PrintModeDefault {
		t.Errorf("PrintMode: got %q, want %q", p.PrintMode, PrintModeDefault)
	}
}

