func TestParseParams_EffectiveTemperatures(t *testing.T) {
	t.Run("T0 takes priority", func(t *testing.T) {
		gcode := `; generated by PrusaSlicer 2.7.0
; printer_model = A350
; first_layer_temperature = 215, 220
; first_layer_bed_temperature = 60, 65
; filament used [mm] = 5000, 3000
` + _padToLines(25)

		gcodes := _parseGcodes(gcode)
		if err := ParseParams(gcodes); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if got := Params.EffectiveNozzleTemperature(); got != 215 {
			t.Errorf("EffectiveNozzleTemperature: got %f, want 215", got)
		}
		if got := Params.EffectiveBedTemperature(); got != 60 {
			t.Errorf("EffectiveBedTemperature: got %f, want 60", got)
		}
	})

	t.Run("falls back to T1 when T0 < 1", func(t *testing.T) {
		gcode := `; generated by PrusaSlicer 2.7.0
; printer_model = A350
; first_layer_temperature = 0, 220
; first_layer_bed_temperature = 0, 65
; filament used [mm] = 0, 3000
` + _padToLines(25)

		gcodes := _parseGcodes(gcode)
		if err := ParseParams(gcodes); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if got := Params.EffectiveNozzleTemperature(); got != 220 {
			t.Errorf("EffectiveNozzleTemperature: got %f, want 220 (fallback to T1)", got)
		}
		if got := Params.EffectiveBedTemperature(); got != 65 {
			t.Errorf("EffectiveBedTemperature: got %f, want 65 (fallback to T1)", got)
		}
	})
}

